CREATE OR REPLACE FUNCTION public.economy_decide_redemption(p_redemption_id uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_redemption record;
  v_reward record;
  v_has_reward boolean := false;
  v_balance bigint;
  v_txn_id uuid;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  end if;

  select id, family_id, reward_id, currency_id, member_id, cost, status
    into v_redemption
    from public.economy_redemptions
   where id = p_redemption_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if not public.can_manage_family(v_redemption.family_id) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if v_redemption.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'already_decided');
  end if;

  if not p_approve then
    update public.economy_redemptions
       set status = 'rejected', decided_by = auth.uid(), decided_at = now(),
           note = left(nullif(trim(coalesce(p_note, '')), ''), 1000)
     where id = v_redemption.id;
    return jsonb_build_object('ok', true, 'status', 'rejected');
  end if;

  if v_redemption.reward_id is not null then
    select id, stock into v_reward
      from public.economy_rewards
     where id = v_redemption.reward_id
       and family_id = v_redemption.family_id
     for update;
    v_has_reward := found;
    if v_has_reward and v_reward.stock is not null and v_reward.stock <= 0 then
      return jsonb_build_object('ok', false, 'reason', 'out_of_stock');
    end if;
  end if;

  -- Lock the member's ledger rows before checking the balance. This makes two
  -- concurrent approvals observe each other's debit instead of overspending.
  perform 1
    from public.currency_transactions
   where family_id = v_redemption.family_id
     and currency_id = v_redemption.currency_id
     and member_id = v_redemption.member_id
   for update;
  select coalesce(sum(case when direction = 'credit' then amount else -amount end), 0)::bigint
    into v_balance
    from public.currency_transactions
   where family_id = v_redemption.family_id
     and currency_id = v_redemption.currency_id
     and member_id = v_redemption.member_id;
  if v_balance < v_redemption.cost then
    return jsonb_build_object('ok', false, 'reason', 'insufficient_tokens');
  end if;

  insert into public.currency_transactions
    (family_id, currency_id, member_id, direction, amount, reason,
     related_type, related_id, created_by)
  values
    (v_redemption.family_id, v_redemption.currency_id, v_redemption.member_id,
     'debit', v_redemption.cost, 'Reward redeemed', 'redemption',
     v_redemption.id, auth.uid())
  returning id into v_txn_id;

  update public.economy_redemptions
     set status = 'fulfilled', txn_id = v_txn_id, decided_by = auth.uid(),
         decided_at = now(), note = left(nullif(trim(coalesce(p_note, '')), ''), 1000)
   where id = v_redemption.id;

  if v_has_reward and v_reward.stock is not null then
    update public.economy_rewards
       set stock = stock - 1
     where id = v_reward.id and stock > 0;
  end if;

  return jsonb_build_object('ok', true, 'status', 'fulfilled', 'txn_id', v_txn_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.guardian_review_suggestion(p_suggestion_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_suggestion record;
  v_rule jsonb;
  v_priority integer;
  v_action public.guardian_routing_mode;
  v_trust_levels text[];
  v_time_start time;
  v_time_end time;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  end if;
  if p_decision not in ('approved', 'dismissed') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_decision');
  end if;

  select * into v_suggestion
    from public.guardian_suggestions
   where id = p_suggestion_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if not public.can_manage_family(v_suggestion.family_id) then
    return jsonb_build_object('ok', false, 'reason', 'forbidden');
  end if;
  if v_suggestion.status <> 'pending' then
    return jsonb_build_object('ok', false, 'reason', 'already_reviewed');
  end if;

  if p_decision = 'approved' then
    -- Trust-changing suggestions update the contact before the suggestion is
    -- marked approved. A missing contact rolls back the entire review.
    if v_suggestion.suggestion_type in ('update_trust', 'block_contact')
       and v_suggestion.proposed_contact_id is not null
       and v_suggestion.proposed_trust_level is not null then
      update public.guardian_contacts
         set trust_level = v_suggestion.proposed_trust_level,
             trust_override = true
       where id = v_suggestion.proposed_contact_id
         and family_id = v_suggestion.family_id;
      if not found then
        return jsonb_build_object('ok', false, 'reason', 'contact_not_found');
      end if;
    end if;

    if v_suggestion.suggestion_type = 'new_rule' then
      v_rule := coalesce(v_suggestion.proposed_rule_data, '{}'::jsonb);
      v_priority := case
        when (v_rule->>'priority') ~ '^[0-9]+$'
          then least((v_rule->>'priority')::numeric, 100000)::integer
        else 100
      end;
      v_action := case v_rule->>'action_routing_mode'
        when 'immediate_ring' then 'immediate_ring'::public.guardian_routing_mode
        when 'immediate_ai_summary' then 'immediate_ai_summary'::public.guardian_routing_mode
        when 'voicemail_first' then 'voicemail_first'::public.guardian_routing_mode
        when 'silent_handling' then 'silent_handling'::public.guardian_routing_mode
        when 'blocked' then 'blocked'::public.guardian_routing_mode
        else 'ai_handle_first'::public.guardian_routing_mode
      end;
      if jsonb_typeof(v_rule->'condition_trust_levels') = 'array' then
        v_trust_levels := array(
          select jsonb_array_elements_text(v_rule->'condition_trust_levels')
        );
      end if;
      if (v_rule->>'condition_time_start') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
        v_time_start := (v_rule->>'condition_time_start')::time;
      end if;
      if (v_rule->>'condition_time_end') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
        v_time_end := (v_rule->>'condition_time_end')::time;
      end if;

      insert into public.guardian_routing_rules
        (family_id, name, description, priority, is_active,
         condition_trust_levels, condition_time_start, condition_time_end,
         action_routing_mode, created_by, ai_suggested, approved_by, approved_at)
      values
        (v_suggestion.family_id,
         left(coalesce(nullif(trim(v_rule->>'name'), ''), 'Suggested Guardian rule'), 200),
         left(nullif(trim(v_rule->>'description'), ''), 2000),
         v_priority,
         case when (v_rule->>'is_active') in ('true', 'false')
           then (v_rule->>'is_active')::boolean
           else true
         end,
         v_trust_levels, v_time_start, v_time_end, v_action,
         auth.uid(), true, auth.uid(), now());
    end if;
  end if;

  update public.guardian_suggestions
     set status = p_decision,
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         review_note = left(nullif(trim(coalesce(p_note, '')), ''), 2000)
   where id = v_suggestion.id;

  insert into public.guardian_audit_log
    (family_id, actor_user_id, actor, action, entity_type, entity_id, detail)
  values
    (v_suggestion.family_id, auth.uid(), 'parent',
     'suggestion.' || p_decision, 'guardian_suggestions', v_suggestion.id,
     jsonb_build_object('suggestion_type', v_suggestion.suggestion_type));

  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$function$

CREATE OR REPLACE FUNCTION public.marketplace_accept_offer(p_offer uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_offer   public.marketplace_offers%rowtype;
  v_listing public.marketplace_listings%rowtype;
  v_caller  uuid;
  v_kind    text;
  v_order   uuid;
begin
  select * into v_offer from public.marketplace_offers where id = p_offer;
  if not found then raise exception 'Offer not found'; end if;
  select * into v_listing from public.marketplace_listings where id = v_offer.listing_id;
  if not found then raise exception 'Listing not found'; end if;

  v_caller := public.marketplace_member_id(v_listing.family_id);
  if v_caller is null or v_listing.member_id is distinct from v_caller then
    raise exception 'Only the listing owner can accept offers';
  end if;
  if v_offer.status <> 'open' then raise exception 'Offer is no longer open'; end if;

  update public.marketplace_listings
     set status = 'claimed', claimed_by = v_offer.member_id, claimed_at = now(), updated_at = now()
   where id = v_listing.id;

  update public.marketplace_offers set status = 'accepted', updated_at = now()
   where id = v_offer.id;
  update public.marketplace_offers set status = 'declined', updated_at = now()
   where listing_id = v_listing.id and status = 'open' and id <> v_offer.id;

  v_kind := case
    when v_listing.kind = 'sell' then 'buy'
    when v_listing.kind in ('rent','borrow','swap','donate','free') then v_listing.kind
    else 'buy'
  end;

  insert into public.marketplace_orders
    (family_id, listing_id, buyer_member, seller_member, kind, status, amount_cents, created_by)
  values
    (v_listing.family_id, v_listing.id, v_offer.member_id, v_listing.member_id, v_kind,
     'confirmed', coalesce(v_offer.amount_cents, v_listing.price_cents), auth.uid())
  returning id into v_order;

  return v_order;
end $function$

CREATE OR REPLACE FUNCTION public.marketplace_buy_now(p_listing_id uuid, p_buyer_member_id uuid, p_buyer_family_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing record;
  v_member_family uuid;
  v_order_id uuid;
  v_now timestamptz := now();
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select family_id into v_member_family
  from public.family_members
  where id = p_buyer_member_id and user_id = auth.uid() and is_active;
  if v_member_family is null or v_member_family is distinct from p_buyer_family_id then
    return jsonb_build_object('ok', false, 'reason', 'unauthorized');
  end if;

  select id, family_id, member_id, buy_now_cents, status, sale_format,
         auction_starts_at, auction_ends_at
  into v_listing
  from public.marketplace_listings
  where id = p_listing_id
  for update;

  if not found then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_listing.sale_format <> 'auction' or v_listing.buy_now_cents is null
    or v_listing.buy_now_cents <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'not_available');
  end if;
  if v_listing.status <> 'available' then
    return jsonb_build_object('ok', false, 'reason', 'not_available');
  end if;
  if v_listing.family_id = p_buyer_family_id then
    return jsonb_build_object('ok', false, 'reason', 'own_listing');
  end if;
  if v_listing.auction_ends_at is null or v_now >= v_listing.auction_ends_at then
    return jsonb_build_object('ok', false, 'reason', 'ended');
  end if;
  if v_listing.auction_starts_at is not null and v_now < v_listing.auction_starts_at then
    return jsonb_build_object('ok', false, 'reason', 'not_started');
  end if;

  update public.marketplace_listings
  set status = 'claimed', claimed_by = p_buyer_member_id,
      claimed_at = v_now, auction_closed_at = v_now, updated_at = v_now
  where id = p_listing_id and status = 'available';

  update public.marketplace_bids
  set status = 'lost'
  where listing_id = p_listing_id and status in ('active', 'outbid');

  insert into public.marketplace_orders
    (family_id, listing_id, buyer_member, seller_member, kind, status,
     amount_cents, notes, created_by)
  values
    (v_listing.family_id, v_listing.id, p_buyer_member_id, v_listing.member_id,
     'buy', 'confirmed', v_listing.buy_now_cents, 'Buy-It-Now', auth.uid())
  returning id into v_order_id;

  return jsonb_build_object('ok', true, 'order_id', v_order_id);
end $function$

CREATE OR REPLACE FUNCTION public.marketplace_set_listing_status(p_listing uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_listing public.marketplace_listings%rowtype;
  v_caller  uuid;
  v_ok      boolean;
begin
  select * into v_listing from public.marketplace_listings where id = p_listing;
  if not found then raise exception 'Listing not found'; end if;

  v_caller := public.marketplace_member_id(v_listing.family_id);
  if v_caller is null or v_listing.member_id is distinct from v_caller then
    raise exception 'Only the listing owner can change this listing';
  end if;

  v_ok := case
    when p_status = 'withdrawn'  then v_listing.status in ('available','pending','claimed')
    when p_status = 'completed'  then v_listing.status in ('claimed','pending')
    when p_status = 'available'  then v_listing.status in ('pending','withdrawn')
    when p_status = 'pending'    then v_listing.status = 'available'
    else false
  end;
  if not v_ok then
    raise exception 'Cannot move listing from % to %', v_listing.status, p_status;
  end if;

  update public.marketplace_listings set status = p_status, updated_at = now()
   where id = v_listing.id;
end $function$

