select jsonb_build_object(
 'reference_guard',to_regprocedure('public.reference_shares_family()')::text,
 'triggers',coalesce((select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('meal_plans','grocery_items') and not t.tgisinternal),'[]'::jsonb),
 'foreign_keys',coalesce((select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('meal_plans','grocery_items') and k.contype='f'),'[]'::jsonb),
 'policies',coalesce((select jsonb_agg(to_jsonb(p)) from pg_policies p where p.schemaname='public' and p.tablename in ('meal_plans','grocery_items')),'[]'::jsonb)
) as metadata;
